package com.vizu.identidade.cadastro.service;
import com.vizu.identidade.cadastro.PessoasController.*; import com.vizu.identidade.cadastro.repository.PessoasRepository; import com.vizu.identidade.integracao.service.OutboxService; import com.vizu.identidade.shared.exception.ResourceNotFoundException; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class PessoasService { private final PessoasRepository r; private final OutboxService outbox; public PessoasService(PessoasRepository r,OutboxService outbox){this.r=r;this.outbox=outbox;} private void requireEmployee(UUID id,UUID t){if(!r.employeeExists(id,t))throw new ResourceNotFoundException("Funcionário");} private void requireClient(UUID id,UUID t){if(!r.clientExists(id,t))throw new ResourceNotFoundException("Cliente");} public List<Map<String,Object>> employees(UUID t){return r.employees(t);} @Transactional public Id createEmployee(UUID t,EmployeeRequest x){UUID id=UUID.randomUUID();r.createEmployee(id,t,x.nome(),x.comissaoPercentual(),x.bio(),x.exibirNoSite());outbox.funcionario(id,t,x.nome(),true,x.exibirNoSite());return new Id(id);} public Map<String,Object> employee(UUID id,UUID t){requireEmployee(id,t);return r.employee(id);} @Transactional public void updateEmployee(UUID id,UUID t,EmployeeRequest x){requireEmployee(id,t);r.updateEmployee(id,x.nome(),x.comissaoPercentual(),x.bio(),x.exibirNoSite());outbox.funcionario(id,t,x.nome(),true,x.exibirNoSite());} @Transactional public void stores(UUID id,UUID t,Ids x){requireEmployee(id,t);for(UUID s:x.ids())if(!r.storeExists(s,t))throw new ResourceNotFoundException("Loja");List<UUID> anteriores=r.employeeStores(id);r.replaceEmployeeStores(id,t,x.ids());for(UUID s:anteriores)if(!x.ids().contains(s))outbox.funcionarioLoja(id,s,t,false);for(UUID s:x.ids())outbox.funcionarioLoja(id,s,t,true);} @Transactional public void employeeActive(UUID id,UUID t,boolean active){requireEmployee(id,t);Map<String,Object> e=r.employee(id);r.setEmployeeActive(id,active);outbox.funcionario(id,t,(String)e.get("nome"),active,(Boolean)e.get("exibir_no_site"));} public List<Map<String,Object>> clients(UUID t){return r.clients(t);} @Transactional public Id createClient(UUID t,ClientRequest x){UUID id=UUID.randomUUID();r.createClient(id,t,x.nome(),x.telefone(),x.email());outbox.cliente(id,t,x.nome(),x.telefone(),true);return new Id(id);} public Map<String,Object> client(UUID id,UUID t){requireClient(id,t);return r.client(id);} @Transactional public void updateClient(UUID id,UUID t,ClientRequest x){requireClient(id,t);r.updateClient(id,x.nome(),x.telefone(),x.email());outbox.cliente(id,t,x.nome(),x.telefone(),true);} @Transactional public void clientActive(UUID id,UUID t,boolean active){requireClient(id,t);Map<String,Object> c=r.client(id);r.setClientActive(id,active);outbox.cliente(id,t,(String)c.get("nome"),(String)c.get("telefone"),active);} }
